CREATE OR REPLACE FUNCTION sync_note_customer() RETURNS trigger AS $$
BEGIN
    IF NEW.note IS DISTINCT FROM COALESCE(OLD.note, '') THEN
        IF NEW.customer_note IS NULL OR NEW.customer_note = OLD.customer_note THEN
            NEW.customer_note := NEW.note;
        END IF;
    END IF;
    IF NEW.customer_note IS DISTINCT FROM COALESCE(OLD.customer_note, '') THEN
        IF NEW.note IS NULL OR NEW.note = OLD.note THEN
            NEW.note := NEW.customer_note;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
